import 'dart:convert';import 'dart:io';import 'package:file_picker/file_picker.dart';import 'package:path_provider/path_provider.dart';import 'package:share_plus/share_plus.dart';import 'package:cross_file/cross_file.dart';import '../data/astro_repository.dart';
class BackupService{
Future<void> exportBackup()async{final payload=jsonEncode(await AstroRepository.instance.exportAll());final dir=await getTemporaryDirectory();final file=File(dir.path+'/astrodaily-backup.json');await file.writeAsString(payload,flush:true);await SharePlus.instance.share(ShareParams(files:[XFile(file.path)],subject:'AstroDaily local backup'));}
Future<Map<String,dynamic>?> readBackup()async{final result=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(result==null)return null;final bytes=result.files.single.bytes;if(bytes==null)throw const FormatException('Cannot read backup file.');if(bytes.length>5*1024*1024)throw const FormatException('Backup exceeds 5 MB.');final value=jsonDecode(utf8.decode(bytes));if(value is! Map<String,dynamic>)throw const FormatException('Invalid backup JSON.');if(value['schema_version']!=1)throw const FormatException('Unsupported backup version.');for(final k in ['settings','saved','journal','reading_history','reminders']){if(value[k] is! List)throw FormatException('Missing or invalid '+k+' section.');}return value;}
}
